import{_ as l}from"./plugin-vue_export-helper.21dcd24c.js";import{o as e,c as i,d as a}from"./app.46a7b862.js";const o={},s=a('<h1 id="course-map-openclaw-\u7528\u4F8B\u5DE5\u7A0B\u9012\u8FDB\u8BFE\u7A0B-part-0-4" tabindex="-1"><a class="header-anchor" href="#course-map-openclaw-\u7528\u4F8B\u5DE5\u7A0B\u9012\u8FDB\u8BFE\u7A0B-part-0-4" aria-hidden="true">#</a> Course Map\uFF5COpenClaw \u7528\u4F8B\u5DE5\u7A0B\u9012\u8FDB\u8BFE\u7A0B\uFF08Part 0~4\uFF09</h1><blockquote><p>\u76EE\u7684\uFF1A\u8FD9\u662F\u201C\u603B\u7EB2 + \u76EE\u5F55 + \u8BC1\u636E\u6765\u6E90\u6620\u5C04\u201D\u3002\u4E0D\u5199\u957F\u6B63\u6587\uFF1B\u6B63\u6587\u91CC\u4F1A\u628A\u6BCF\u6761\u6620\u5C04\u5C55\u5F00\u4E3A\uFF1A\u771F\u5B9E\u573A\u666F \u2192 \u5931\u8D25\u70B9 \u2192 \u5173\u952E\u8F6C\u6298 \u2192 SOP \u2192 \u4F5C\u4E1A\uFF0C\u5E76\u9644 sessionKey/time/quote\u3002</p></blockquote><hr><h2 id="part-0-\u4ECE-\u80FD\u8DD1-\u5230-\u53EF\u590D\u7528-\u7528\u4F8B\u5DE5\u7A0B\u65B9\u6CD5" tabindex="-1"><a class="header-anchor" href="#part-0-\u4ECE-\u80FD\u8DD1-\u5230-\u53EF\u590D\u7528-\u7528\u4F8B\u5DE5\u7A0B\u65B9\u6CD5" aria-hidden="true">#</a> Part 0\uFF5C\u4ECE\u201C\u80FD\u8DD1\u201D\u5230\u201C\u53EF\u590D\u7528\u201D\uFF1A\u7528\u4F8B\u5DE5\u7A0B\u65B9\u6CD5</h2><h3 id="lesson-0-1-\u4EC0\u4E48\u53EB-\u53EF\u590D\u7528\u7528\u4F8B-\u4ECE\u4E00\u6B21\u6210\u529F\u5230\u4E00\u5957\u6A21\u677F" tabindex="-1"><a class="header-anchor" href="#lesson-0-1-\u4EC0\u4E48\u53EB-\u53EF\u590D\u7528\u7528\u4F8B-\u4ECE\u4E00\u6B21\u6210\u529F\u5230\u4E00\u5957\u6A21\u677F" aria-hidden="true">#</a> Lesson 0.1\uFF5C\u4EC0\u4E48\u53EB\u201C\u53EF\u590D\u7528\u7528\u4F8B\u201D\uFF1F\u4ECE\u4E00\u6B21\u6210\u529F\u5230\u4E00\u5957\u6A21\u677F</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u4E3A\u4EC0\u4E48\u201C\u8DD1\u901A\u4E00\u6B21\u201D\u4E0D\u7B49\u4E8E\u201C\u53EF\u590D\u7528\u201D\uFF1F\u600E\u6837\u628A\u6210\u529F\u6C89\u6DC0\u4E3A\u6A21\u677F\uFF08reuse_template\uFF09\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u7528\u4F8B\u5361\uFF08Problem / Workflow / Outcome / Reuse template / Unknowns / Tags\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF08\u7528\u4F8B\u6807\u9898\uFF09\uFF1A <ol><li>Codex \u591A\u8D26\u53F7\u989D\u5EA6\u5DE1\u68C0\u4E0E auth order \u81EA\u52A8\u91CD\u6392</li><li>\u6BCF\u5C0F\u65F6 Stash \u7F51\u7EDC\u63A2\u6D4B + \u5F02\u5E38\u624D\u901A\u77E5</li><li>30G \u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0\u7684\u6B62\u635F\u4FEE\u590D\uFF1A\u5220\u6587\u4EF6 + \u5173 cacheTrace + \u56DE\u5F52\u9A8C\u8BC1</li></ol></li></ul><h3 id="lesson-0-2-\u8BC1\u636E\u9A71\u52A8-\u5982\u4F55\u7528-sessionkey-time-quote-\u7ED9\u7ED3\u8BBA\u4E0A-\u94A2\u5370" tabindex="-1"><a class="header-anchor" href="#lesson-0-2-\u8BC1\u636E\u9A71\u52A8-\u5982\u4F55\u7528-sessionkey-time-quote-\u7ED9\u7ED3\u8BBA\u4E0A-\u94A2\u5370" aria-hidden="true">#</a> Lesson 0.2\uFF5C\u8BC1\u636E\u9A71\u52A8\uFF1A\u5982\u4F55\u7528 sessionKey/time/quote \u7ED9\u7ED3\u8BBA\u4E0A\u201C\u94A2\u5370\u201D</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u56E2\u961F\u5206\u4EAB\u91CC\uFF0C\u5982\u4F55\u907F\u514D\u201C\u6211\u611F\u89C9/\u5E94\u8BE5\u662F\u201D\uFF1F\u600E\u6837\u628A\u7ED3\u8BBA\u951A\u5B9A\u5230\u53EF\u56DE\u653E\u7684\u8BC1\u636E\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u8BC1\u636E\u951A\u70B9\u201D\u5199\u4F5C\u89C4\u8303\uFF08\u6BCF\u4E2A\u5173\u952E\u7ED3\u8BBA \u22651 \u4E2A quote\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u4F1A\u8BDD\u9A71\u52A8\u81EA\u8FDB\u5316\uFF1A24h \u4FE1\u53F7\u91C7\u96C6\u5E76\u66F4\u65B0 skill-gaps</li><li>\u4E89\u8BAE\u4FE1\u606F\u7528\u2018\u5B9E\u6D4B + \u5B98\u65B9\u89C4\u5219\u9875\u2019\u53CC\u8BC1\u636E\u5B9A\u6027</li></ol></li></ul><hr><h2 id="part-1-\u5931\u8D25\u662F\u4E3B\u7EBF-\u628A\u5E38\u89C1\u6545\u969C\u53D8\u6210\u53EF\u81EA\u52A8\u964D\u7EA7\u7684-sop" tabindex="-1"><a class="header-anchor" href="#part-1-\u5931\u8D25\u662F\u4E3B\u7EBF-\u628A\u5E38\u89C1\u6545\u969C\u53D8\u6210\u53EF\u81EA\u52A8\u964D\u7EA7\u7684-sop" aria-hidden="true">#</a> Part 1\uFF5C\u5931\u8D25\u662F\u4E3B\u7EBF\uFF1A\u628A\u5E38\u89C1\u6545\u969C\u53D8\u6210\u53EF\u81EA\u52A8\u964D\u7EA7\u7684 SOP</h2><h3 id="lesson-1-1-\u68C0\u7D22\u94FE\u8DEF\u4E09\u8FDE\u51FB-429-fetch-failed-\u672C\u5730\u547D\u4EE4\u9519\u8BEF" tabindex="-1"><a class="header-anchor" href="#lesson-1-1-\u68C0\u7D22\u94FE\u8DEF\u4E09\u8FDE\u51FB-429-fetch-failed-\u672C\u5730\u547D\u4EE4\u9519\u8BEF" aria-hidden="true">#</a> Lesson 1.1\uFF5C\u68C0\u7D22\u94FE\u8DEF\u4E09\u8FDE\u51FB\uFF1A429 + fetch failed + \u672C\u5730\u547D\u4EE4\u9519\u8BEF</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53\u68C0\u7D22\u5C42\uFF08429/\u6293\u53D6\u5931\u8D25\uFF09\u548C\u6267\u884C\u5C42\uFF08python \u4E0D\u5B58\u5728\uFF09\u540C\u65F6\u70B8\u65F6\uFF0C\u5982\u4F55\u8BA9\u4EFB\u52A1\u4ECD\u80FD\u201C\u6309\u65F6\u4EA4\u4ED8\u201D\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u5206\u7EA7\u6545\u969C\u5904\u7F6E\u8868\u201D\uFF08\u68C0\u7D22\u5931\u8D25\u2192DDG \u515C\u5E95\uFF1B\u547D\u4EE4\u5931\u8D25\u2192\u89E3\u91CA\u5668\u4FEE\u6B63\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>Brave 429 + fetch failed + python \u547D\u4EE4\u9519\u8BEF\u7684\u591A\u6545\u969C\u4E32\u8054\u4FEE\u590D</li><li>AI \u516C\u53F8\u52A8\u6001\u76D1\u63A7\uFF1A\u68C0\u7D22\u9000\u907F + \u591A\u6E90\u515C\u5E95 + 24h \u65F6\u7A97</li></ol></li></ul><h3 id="lesson-1-2-web-fetch-\u88AB\u79C1\u7F51-ip-\u7B56\u7565\u62E6\u622A-\u5982\u4F55\u65E0\u75DB\u5207\u6362\u6293\u53D6\u94FE\u8DEF" tabindex="-1"><a class="header-anchor" href="#lesson-1-2-web-fetch-\u88AB\u79C1\u7F51-ip-\u7B56\u7565\u62E6\u622A-\u5982\u4F55\u65E0\u75DB\u5207\u6362\u6293\u53D6\u94FE\u8DEF" aria-hidden="true">#</a> Lesson 1.2\uFF5Cweb_fetch \u88AB\u79C1\u7F51 IP \u7B56\u7565\u62E6\u622A\uFF1A\u5982\u4F55\u65E0\u75DB\u5207\u6362\u6293\u53D6\u94FE\u8DEF</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53 web_fetch \u62A5 \u201CBlocked: resolves to private/internal/special-use IP address\u201D \u65F6\uFF0C\u600E\u6837\u4FDD\u6301\u4EFB\u52A1\u4E0D\u65AD\u7EBF\uFF0C\u5E76\u4E14\u8BA9\u964D\u7EA7\u8DEF\u5F84\u53EF\u590D\u7528\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u6293\u53D6\u94FE\u8DEF\u8DEF\u7531\u5668\u201DSOP\uFF08web_fetch \u2192 browser \u6293\u53D6 \u2192 web_search \u8865\u8BC1 \u2192 \u539F\u6295\u9012\u94FE\u8DEF\u4E0D\u53D8\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>web_fetch \u88AB\u79C1\u7F51 IP \u7B56\u7565\u62E6\u622A\u540E\uFF0C\u5207\u6362\u6293\u53D6\u94FE\u8DEF\u5B8C\u6210\u5B9A\u65F6\u64AD\u62A5</li><li>\u540C\u7C7B\u79C1\u7F51\u62E6\u622A\u5728\u53E6\u4E00\u6761 cron \u590D\u73B0\uFF0C\u9A8C\u8BC1 fallback \u53EF\u590D\u7528</li><li>AI \u516C\u53F8\u52A8\u6001\u76D1\u63A7\uFF1A\u68C0\u7D22\u9000\u907F + \u591A\u6E90\u515C\u5E95 + 24h \u65F6\u7A97</li></ol></li></ul><h3 id="lesson-1-3-fakeip-\u73AF\u5883\u4E0B\u7684\u8BCA\u65AD\u7EA0\u504F-\u522B\u518D\u88AB-dig-nslookup-\u5E26\u6C9F\u91CC" tabindex="-1"><a class="header-anchor" href="#lesson-1-3-fakeip-\u73AF\u5883\u4E0B\u7684\u8BCA\u65AD\u7EA0\u504F-\u522B\u518D\u88AB-dig-nslookup-\u5E26\u6C9F\u91CC" aria-hidden="true">#</a> Lesson 1.3\uFF5CFakeIP \u73AF\u5883\u4E0B\u7684\u8BCA\u65AD\u7EA0\u504F\uFF1A\u522B\u518D\u88AB dig/nslookup \u5E26\u6C9F\u91CC</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u4E3A\u4EC0\u4E48\u5728\u4EE3\u7406 FakeIP \u73AF\u5883\u4E0B\uFF0CDNS \u7ED3\u679C\u53EF\u80FD\u662F\u201C\u5047\u8C61\u201D\uFF1F\u5982\u4F55\u5EFA\u7ACB\u201C\u771F\u5B9E\u8BBF\u95EE\u94FE\u8DEF\u4F18\u5148\u201D\u7684\u6392\u969C\u89C4\u5219\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u56E2\u961F\u7EA7\u6392\u969C SOP\uFF08\u7981\u6B62\u5355\u770B DNS\uFF1B\u5FC5\u987B\u7528\u6D4F\u89C8\u5668\u5B9E\u6D4B/\u4EE3\u7406\u5185\u94FE\u8DEF\u590D\u6D4B\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>FakeIP \u7F51\u7EDC\u73AF\u5883\u4E0B\u7684\u8BCA\u65AD\u7EA0\u504F\u6D41\u7A0B</li></ol></li></ul><hr><h2 id="part-2-\u76D1\u63A7\u4E0E\u64AD\u62A5-\u505A-\u5F02\u5E38\u4F18\u5148\u3001\u4E0D\u5237\u5C4F-\u7684-cron-\u4F53\u7CFB" tabindex="-1"><a class="header-anchor" href="#part-2-\u76D1\u63A7\u4E0E\u64AD\u62A5-\u505A-\u5F02\u5E38\u4F18\u5148\u3001\u4E0D\u5237\u5C4F-\u7684-cron-\u4F53\u7CFB" aria-hidden="true">#</a> Part 2\uFF5C\u76D1\u63A7\u4E0E\u64AD\u62A5\uFF1A\u505A\u201C\u5F02\u5E38\u4F18\u5148\u3001\u4E0D\u5237\u5C4F\u201D\u7684 cron \u4F53\u7CFB</h2><h3 id="lesson-2-1-\u6BCF\u5C0F\u65F6\u5DE1\u68C0\u4E0D\u7B49\u4E8E\u6BCF\u5C0F\u65F6\u5237\u5C4F-\u901A\u77E5\u95E8\u7981\u600E\u4E48\u505A" tabindex="-1"><a class="header-anchor" href="#lesson-2-1-\u6BCF\u5C0F\u65F6\u5DE1\u68C0\u4E0D\u7B49\u4E8E\u6BCF\u5C0F\u65F6\u5237\u5C4F-\u901A\u77E5\u95E8\u7981\u600E\u4E48\u505A" aria-hidden="true">#</a> Lesson 2.1\uFF5C\u6BCF\u5C0F\u65F6\u5DE1\u68C0\u4E0D\u7B49\u4E8E\u6BCF\u5C0F\u65F6\u5237\u5C4F\uFF1A\u901A\u77E5\u95E8\u7981\u600E\u4E48\u505A</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5982\u4F55\u5728\u201C\u6301\u7EED\u76D1\u63A7\u201D\u548C\u201C\u7FA4\u91CC\u4E0D\u88AB\u5237\u5C4F\u201D\u4E4B\u95F4\u505A\u5DE5\u7A0B\u5316\u5E73\u8861\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u901A\u77E5\u95E8\u7981\u201D\u8BBE\u8BA1\uFF08\u5F02\u5E38\u624D\u53D1 + \u63D0\u9192\u7A97\u53E3 + threadId \u5F52\u6863\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u6BCF\u5C0F\u65F6 Stash \u7F51\u7EDC\u63A2\u6D4B + \u5F02\u5E38\u624D\u901A\u77E5</li><li>AI \u516C\u53F8\u52A8\u6001\u76D1\u63A7\uFF1A\u68C0\u7D22\u9000\u907F + \u591A\u6E90\u515C\u5E95 + 24h \u65F6\u7A97</li></ol></li></ul><h3 id="lesson-2-2-cron-\u5931\u8D25\u540E\u7684\u5FEB\u901F\u590D\u76D8-\u624B\u52A8\u8865\u8DD1\u95ED\u73AF" tabindex="-1"><a class="header-anchor" href="#lesson-2-2-cron-\u5931\u8D25\u540E\u7684\u5FEB\u901F\u590D\u76D8-\u624B\u52A8\u8865\u8DD1\u95ED\u73AF" aria-hidden="true">#</a> Lesson 2.2\uFF5Ccron \u5931\u8D25\u540E\u7684\u5FEB\u901F\u590D\u76D8 + \u624B\u52A8\u8865\u8DD1\u95ED\u73AF</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1Acron \u5931\u8D25\u65F6\uFF0C\u600E\u6837\u5FEB\u901F\u56DE\u7B54\u4E09\u4E2A\u95EE\u9898\uFF1A\u5931\u8D25\u53D1\u751F\u5728\u4F55\u65F6\uFF1F\u4E3A\u4EC0\u4E48\u5931\u8D25\uFF1F\u73B0\u5728\u5982\u4F55\u7ACB\u523B\u6062\u590D\u53EF\u4FE1\u7ED3\u679C\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u5931\u8D25\u590D\u76D8\u6A21\u677F\u201D\uFF08\u65F6\u95F4\u7A97\u53E3 + \u9519\u8BEF\u539F\u56E0 + \u6297\u6296\u53C2\u6570\u5EFA\u8BAE + \u7ACB\u523B\u8865\u8DD1\u56DE\u6267\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>Cron\u4EFB\u52A1\u5F02\u5E38\u540E\u5FEB\u901F\u590D\u76D8 + \u624B\u52A8\u8865\u8DD1\u95ED\u73AF</li><li>Gateway \u8D85\u65F6\u6296\u52A8\u573A\u666F\u4E0B\uFF0C\u7528\u53EF\u7528\u8BFB\u64CD\u4F5C\u7EF4\u6301\u8BCA\u65AD\u95ED\u73AF</li></ol></li></ul><h3 id="lesson-2-3-\u53CC\u76EE\u5F55-git-\u81EA\u52A8\u5907\u4EFD-\u5931\u8D25\u53EF\u89C1\u5316\u3001\u7ED3\u679C\u53EF\u8FFD\u8E2A" tabindex="-1"><a class="header-anchor" href="#lesson-2-3-\u53CC\u76EE\u5F55-git-\u81EA\u52A8\u5907\u4EFD-\u5931\u8D25\u53EF\u89C1\u5316\u3001\u7ED3\u679C\u53EF\u8FFD\u8E2A" aria-hidden="true">#</a> Lesson 2.3\uFF5C\u53CC\u76EE\u5F55 Git \u81EA\u52A8\u5907\u4EFD\uFF1A\u5931\u8D25\u53EF\u89C1\u5316\u3001\u7ED3\u679C\u53EF\u8FFD\u8E2A</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53\u8981\u5907\u4EFD\u4E24\u4E2A\u5173\u952E\u76EE\u5F55\u65F6\uFF0C\u5982\u4F55\u4FDD\u8BC1\u201C\u8C01\u6210\u529F\u8C01\u5931\u8D25\u4E00\u773C\u53EF\u89C1\u201D\uFF0C\u5E76\u4E14\u4FDD\u7559\u53EF\u8FFD\u8E2A\u7684 commit \u8BC1\u636E\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u591A\u76EE\u6807\u4EFB\u52A1\u7EDF\u4E00\u6C47\u603B\u683C\u5F0F\u201D\uFF08\u6210\u529F/\u5931\u8D25/\u65E0\u53D8\u66F4 + \u539F\u56E0 + hash\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u53CC\u76EE\u5F55 Git \u81EA\u52A8\u5907\u4EFD + \u5931\u8D25\u53EF\u89C1\u5316\u64AD\u62A5</li></ol></li></ul><hr><h2 id="part-3-\u751F\u4EA7\u5316\u4E0E\u7A33\u5B9A\u6027\u5DE5\u7A0B-\u4E8B\u6545\u3001\u53EF\u89C2\u6D4B\u3001\u56DE\u5F52\u9A8C\u8BC1" tabindex="-1"><a class="header-anchor" href="#part-3-\u751F\u4EA7\u5316\u4E0E\u7A33\u5B9A\u6027\u5DE5\u7A0B-\u4E8B\u6545\u3001\u53EF\u89C2\u6D4B\u3001\u56DE\u5F52\u9A8C\u8BC1" aria-hidden="true">#</a> Part 3\uFF5C\u751F\u4EA7\u5316\u4E0E\u7A33\u5B9A\u6027\u5DE5\u7A0B\uFF1A\u4E8B\u6545\u3001\u53EF\u89C2\u6D4B\u3001\u56DE\u5F52\u9A8C\u8BC1</h2><h3 id="lesson-3-1-30g-\u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0-\u6B62\u635F\u4E09\u6B65\u6CD5-\u91CF\u5316\u2192\u6E05\u7406\u2192\u5173\u589E\u91CF" tabindex="-1"><a class="header-anchor" href="#lesson-3-1-30g-\u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0-\u6B62\u635F\u4E09\u6B65\u6CD5-\u91CF\u5316\u2192\u6E05\u7406\u2192\u5173\u589E\u91CF" aria-hidden="true">#</a> Lesson 3.1\uFF5C30G \u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0\uFF1A\u6B62\u635F\u4E09\u6B65\u6CD5\uFF08\u91CF\u5316\u2192\u6E05\u7406\u2192\u5173\u589E\u91CF\uFF09</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53\u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0\u5230\u51E0\u5341 GB\uFF0C\u5982\u4F55\u201C\u7ACB\u523B\u6B62\u8840 + \u907F\u514D\u590D\u53D1 + \u4E0D\u5F15\u5165\u65B0\u4E8B\u6545\u201D\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E8B\u6545\u6B62\u635F Runbook\uFF08\u786E\u8BA4\u4F53\u79EF\u2192\u505C/\u4E0D\u505C\u7F51\u5173\u7B56\u7565\u2192\u6E05\u7406\u2192\u5173\u95ED\u5F00\u5173\u2192\u56DE\u5F52\u9A8C\u8BC1\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>30G \u8BCA\u65AD\u65E5\u5FD7\u81A8\u80C0\u7684\u6B62\u635F\u4FEE\u590D\uFF1A\u5220\u6587\u4EF6 + \u5173 cacheTrace + \u56DE\u5F52\u9A8C\u8BC1</li></ol></li></ul><h3 id="lesson-3-2-gateway-timeout-\u6296\u52A8-\u7528-\u591A\u547D\u4EE4\u63A2\u9488-\u7EF4\u6301\u8BCA\u65AD\u95ED\u73AF" tabindex="-1"><a class="header-anchor" href="#lesson-3-2-gateway-timeout-\u6296\u52A8-\u7528-\u591A\u547D\u4EE4\u63A2\u9488-\u7EF4\u6301\u8BCA\u65AD\u95ED\u73AF" aria-hidden="true">#</a> Lesson 3.2\uFF5CGateway timeout \u6296\u52A8\uFF1A\u7528\u201C\u591A\u547D\u4EE4\u63A2\u9488\u201D\u7EF4\u6301\u8BCA\u65AD\u95ED\u73AF</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53\u7F51\u5173\u8D85\u65F6\u5BFC\u81F4\u90E8\u5206\u547D\u4EE4\u4E0D\u53EF\u7528\u65F6\uFF0C\u600E\u6837\u7528\u201C\u53EF\u8FD4\u56DE\u7684\u8BFB\u64CD\u4F5C\u201D\u62FC\u51FA\u6700\u5C0F\u53EF\u884C\u8BCA\u65AD\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u591A\u547D\u4EE4\u63A2\u9488\u201D\u7B56\u7565\u6E05\u5355\uFF08status/list \u7B49\u66FF\u4EE3\u5355\u70B9\u547D\u4EE4\u4F9D\u8D56\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>Gateway \u8D85\u65F6\u6296\u52A8\u573A\u666F\u4E0B\uFF0C\u7528\u53EF\u7528\u8BFB\u64CD\u4F5C\u7EF4\u6301\u8BCA\u65AD\u95ED\u73AF</li><li>Cron\u4EFB\u52A1\u5F02\u5E38\u540E\u5FEB\u901F\u590D\u76D8 + \u624B\u52A8\u8865\u8DD1\u95ED\u73AF</li></ol></li></ul><h3 id="lesson-3-3-\u7B2C\u4E09\u65B9\u6280\u80FD\u4E0A\u7EBF-\u5BC6\u94A5\u843D\u5730-\u8054\u8C03\u9A8C\u6536\u7684\u6807\u51C6\u6D41\u7A0B" tabindex="-1"><a class="header-anchor" href="#lesson-3-3-\u7B2C\u4E09\u65B9\u6280\u80FD\u4E0A\u7EBF-\u5BC6\u94A5\u843D\u5730-\u8054\u8C03\u9A8C\u6536\u7684\u6807\u51C6\u6D41\u7A0B" aria-hidden="true">#</a> Lesson 3.3\uFF5C\u7B2C\u4E09\u65B9\u6280\u80FD\u4E0A\u7EBF\uFF1A\u5BC6\u94A5\u843D\u5730 + \u8054\u8C03\u9A8C\u6536\u7684\u6807\u51C6\u6D41\u7A0B</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u4E3A\u4EC0\u4E48\u201C\u88C5\u4E0A\u4E86\u201D\u4E0D\u7B49\u4E8E\u201C\u80FD\u7528\u201D\uFF1F\u5982\u4F55\u628A token/\u767B\u5F55\u6001\u8FD9\u4E2A\u6700\u5927\u4E0D\u786E\u5B9A\u6027\uFF0C\u53D8\u6210\u53EF\u5BA1\u8BA1\u3001\u53EF\u9A8C\u8BC1\u7684\u4E0A\u7EBF\u6D41\u7A0B\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u6280\u80FD\u4E0A\u7EBF SOP\uFF08\u5B89\u88C5\u2192\u7F3A\u53E3\u5B9A\u4F4D\u2192\u5B89\u5168\u5199 env\u2192API \u7EA7\u9A8C\u6536\u2192\u4E1A\u52A1\u7EA7\u5B9E\u6D4B\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u7B2C\u4E09\u65B9\u6280\u80FD\u63A5\u5165\u7684\u2018\u5BC6\u94A5\u843D\u5730 + \u8054\u8C03\u9A8C\u6536\u2019\u6807\u51C6\u6D41\u7A0B</li></ol></li></ul><hr><h2 id="part-4-\u8FDB\u9636-\u4E0A\u4E0B\u6587\u5DE5\u7A0B\u3001\u8D44\u6E90\u6CBB\u7406\u3001\u7EC4\u7EC7\u843D\u5730" tabindex="-1"><a class="header-anchor" href="#part-4-\u8FDB\u9636-\u4E0A\u4E0B\u6587\u5DE5\u7A0B\u3001\u8D44\u6E90\u6CBB\u7406\u3001\u7EC4\u7EC7\u843D\u5730" aria-hidden="true">#</a> Part 4\uFF5C\u8FDB\u9636\uFF1A\u4E0A\u4E0B\u6587\u5DE5\u7A0B\u3001\u8D44\u6E90\u6CBB\u7406\u3001\u7EC4\u7EC7\u843D\u5730</h2><h3 id="lesson-4-1-\u591A\u8D26\u53F7\u989D\u5EA6\u5DE1\u68C0\u4E0E-auth-order-\u81EA\u52A8\u91CD\u6392-\u628A\u8D44\u6E90\u6CBB\u7406\u4EA7\u54C1\u5316" tabindex="-1"><a class="header-anchor" href="#lesson-4-1-\u591A\u8D26\u53F7\u989D\u5EA6\u5DE1\u68C0\u4E0E-auth-order-\u81EA\u52A8\u91CD\u6392-\u628A\u8D44\u6E90\u6CBB\u7406\u4EA7\u54C1\u5316" aria-hidden="true">#</a> Lesson 4.1\uFF5C\u591A\u8D26\u53F7\u989D\u5EA6\u5DE1\u68C0\u4E0E auth order \u81EA\u52A8\u91CD\u6392\uFF1A\u628A\u8D44\u6E90\u6CBB\u7406\u4EA7\u54C1\u5316</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u591A\u8D26\u53F7\u5E76\u884C\u65F6\uFF0C\u5982\u4F55\u6BCF\u5929\u81EA\u52A8\u68C0\u67E5\u5065\u5EB7\u5EA6\u4E0E\u989D\u5EA6\uFF0C\u5E76\u628A\u6392\u5E8F\u89C4\u5219\u201C\u663E\u5F0F\u5316 + \u53EF\u590D\u6838\u201D\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u8D44\u6E90\u6CBB\u7406 SOP\uFF08\u5065\u5EB7\u68C0\u67E5\u2192\u989D\u5EA6\u91C7\u96C6\u2192\u6392\u5E8F\u2192set\u2192get \u590D\u6838\u2192\u7B80\u62A5\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>Codex \u591A\u8D26\u53F7\u989D\u5EA6\u5DE1\u68C0\u4E0E auth order \u81EA\u52A8\u91CD\u6392</li><li>Cron\u4EFB\u52A1\u5F02\u5E38\u540E\u5FEB\u901F\u590D\u76D8 + \u624B\u52A8\u8865\u8DD1\u95ED\u73AF</li></ol></li></ul><h3 id="lesson-4-2-overnight-goal-autopilot-\u591C\u95F4\u65E0\u4EBA\u503C\u5B88\u4E5F\u80FD\u4EA7\u51FA-\u884C\u52A8\u5305" tabindex="-1"><a class="header-anchor" href="#lesson-4-2-overnight-goal-autopilot-\u591C\u95F4\u65E0\u4EBA\u503C\u5B88\u4E5F\u80FD\u4EA7\u51FA-\u884C\u52A8\u5305" aria-hidden="true">#</a> Lesson 4.2\uFF5COvernight Goal Autopilot\uFF1A\u591C\u95F4\u65E0\u4EBA\u503C\u5B88\u4E5F\u80FD\u4EA7\u51FA\u201C\u884C\u52A8\u5305\u201D</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u600E\u4E48\u8BA9\u201C\u957F\u671F\u76EE\u6807\u201D\u4E0D\u518D\u505C\u7559\u5728\u53E3\u53F7\uFF0C\u800C\u662F\u6BCF\u5929\u81EA\u52A8\u4EA7\u51FA\u53EF\u6267\u884C\u6587\u6863\uFF0C\u5E76\u5F62\u6210\u8FDE\u7EED\u8FED\u4EE3\u8282\u594F\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u201C\u76EE\u6807\u8BF4\u660E\u4E66\u9A71\u52A8\u201D\u7684\u4EA7\u7EBF\u7ED3\u6784\uFF08\u56FA\u5B9A\u8F93\u5165\u2192\u56FA\u5B9A\u8F93\u51FA\u76EE\u5F55\u2192\u4E00\u6B21\u6027\u901A\u77E5\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>Overnight Goal Autopilot\uFF1A\u8BFB\u76EE\u6807\u6587\u6863\u540E\u81EA\u52A8\u4EA7\u51FA\u884C\u52A8\u5305</li><li>\u957F\u671F\u9879\u76EE\u4EA7\u7269\u76EE\u5F55\u91CD\u6784\uFF08\u6839\u76EE\u5F55\u51CF\u8D1F\uFF09</li></ol></li></ul><h3 id="lesson-4-3-\u4F1A\u8BDD\u9A71\u52A8\u81EA\u8FDB\u5316-24h-\u4FE1\u53F7\u91C7\u96C6\u5E76\u66F4\u65B0-skill-gaps" tabindex="-1"><a class="header-anchor" href="#lesson-4-3-\u4F1A\u8BDD\u9A71\u52A8\u81EA\u8FDB\u5316-24h-\u4FE1\u53F7\u91C7\u96C6\u5E76\u66F4\u65B0-skill-gaps" aria-hidden="true">#</a> Lesson 4.3\uFF5C\u4F1A\u8BDD\u9A71\u52A8\u81EA\u8FDB\u5316\uFF1A24h \u4FE1\u53F7\u91C7\u96C6\u5E76\u66F4\u65B0 skill-gaps</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5982\u4F55\u4E0D\u9760\u4E3B\u89C2\u5370\u8C61\uFF0C\u800C\u662F\u4ECE\u771F\u5B9E\u4F1A\u8BDD\u91CC\u6301\u7EED\u62BD\u53D6\u80FD\u529B\u7F3A\u53E3\uFF0C\u5E76\u5F62\u6210\u957F\u671F\u6539\u8FDB\u5E93\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u5957\u201C\u4FE1\u53F7\u89C4\u5219 + \u626B\u63CF\u8303\u56F4 + \u53BB\u91CD\u5199\u5165\u201D\u7684\u81EA\u8FDB\u5316\u7BA1\u9053\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u4F1A\u8BDD\u9A71\u52A8\u81EA\u8FDB\u5316\uFF1A24h \u4FE1\u53F7\u91C7\u96C6\u5E76\u66F4\u65B0 skill-gaps</li></ol></li></ul><h3 id="lesson-4-4-\u591A-bot-\u534F\u4F5C\u7A33\u5B9A\u6027-hold-timeout-stop-\u9632\u5931\u63A7" tabindex="-1"><a class="header-anchor" href="#lesson-4-4-\u591A-bot-\u534F\u4F5C\u7A33\u5B9A\u6027-hold-timeout-stop-\u9632\u5931\u63A7" aria-hidden="true">#</a> Lesson 4.4\uFF5C\u591A Bot \u534F\u4F5C\u7A33\u5B9A\u6027\uFF1AHOLD/TIMEOUT/STOP \u9632\u5931\u63A7</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u591A Agent/\u591A Bot \u534F\u4F5C\u65F6\uFF0C\u5982\u4F55\u9632\u6B62\u4E0A\u4E0B\u6587\u6F02\u79FB\u3001\u65E0\u89E6\u53D1\u7EE7\u7EED\u3001\u9519\u8BEF\u5FAA\u73AF\u4E0E\u5237\u5C4F\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u53EF\u6267\u884C\u534F\u4F5C\u534F\u8BAE\uFF08trigger gate + hold-once + timeout + fail-stop\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u591A Bot \u534F\u4F5C\u7A33\u5B9A\u6027\u89C4\u5219\u5316\uFF1AHOLD/TIMEOUT/STOP \u9632\u5931\u63A7</li></ol></li></ul><h3 id="lesson-4-5-\u4E89\u8BAE\u4FE1\u606F\u5982\u4F55\u5B9A\u6027-\u5B9E\u6D4B-\u5B98\u65B9\u89C4\u5219\u9875\u7684\u53CC\u8BC1\u636E\u7B56\u7565" tabindex="-1"><a class="header-anchor" href="#lesson-4-5-\u4E89\u8BAE\u4FE1\u606F\u5982\u4F55\u5B9A\u6027-\u5B9E\u6D4B-\u5B98\u65B9\u89C4\u5219\u9875\u7684\u53CC\u8BC1\u636E\u7B56\u7565" aria-hidden="true">#</a> Lesson 4.5\uFF5C\u4E89\u8BAE\u4FE1\u606F\u5982\u4F55\u5B9A\u6027\uFF1A\u5B9E\u6D4B + \u5B98\u65B9\u89C4\u5219\u9875\u7684\u53CC\u8BC1\u636E\u7B56\u7565</h3><ul><li>\u6838\u5FC3\u95EE\u9898\uFF1A\u5F53\u5916\u90E8\u8BF4\u6CD5\u51B2\u7A81\u65F6\uFF0C\u600E\u6837\u7528\u201C\u7AD9\u70B9\u5B9E\u6D4B + \u5B98\u65B9\u89C4\u5219\u6587\u672C\u201D\u628A\u7ED3\u8BBA\u505A\u5B9E\uFF0C\u5E76\u660E\u786E\u4E0D\u786E\u5B9A\u6027\u8FB9\u754C\uFF1F</li><li>\u4F60\u4F1A\u4EA7\u51FA\u7684\u4E1C\u897F\uFF1A\u4E00\u4EFD\u4FE1\u606F\u6838\u9A8C SOP\uFF08\u5165\u53E3\u5B9E\u6D4B\u2192\u89C4\u5219\u9875\u6293\u53D6\u2192\u51B2\u7A81\u5904\u7406\u2192\u8F93\u51FA\u53EF\u4FE1\u53E3\u5F84\uFF09\u3002</li><li>\u8BC1\u636E\u6765\u6E90\u6620\u5C04\uFF1A <ol><li>\u4E89\u8BAE\u4FE1\u606F\u7528\u2018\u5B9E\u6D4B + \u5B98\u65B9\u89C4\u5219\u9875\u2019\u53CC\u8BC1\u636E\u5B9A\u6027</li></ol></li></ul><hr><h2 id="\u9644-\u53EF\u9009\u52A0\u9910-\u5982\u679C\u9700\u8981\u6269\u5C55\u8BFE\u7A0B" tabindex="-1"><a class="header-anchor" href="#\u9644-\u53EF\u9009\u52A0\u9910-\u5982\u679C\u9700\u8981\u6269\u5C55\u8BFE\u7A0B" aria-hidden="true">#</a> \u9644\uFF1A\u53EF\u9009\u52A0\u9910\uFF08\u5982\u679C\u9700\u8981\u6269\u5C55\u8BFE\u7A0B\uFF09</h2><blockquote><p>\u8FD9\u4E9B\u7528\u4F8B\u53EF\u4EE5\u4F5C\u4E3A\u201C\u8BFE\u540E\u62D3\u5C55/\u5B9E\u64CD\u6311\u6218\u201D\uFF0C\u4E0D\u4E00\u5B9A\u8FDB\u4E3B\u7EBF\u3002</p></blockquote><ol><li>AI \u516C\u53F8\u52A8\u6001\u76D1\u63A7\uFF1A\u68C0\u7D22\u9000\u907F + \u591A\u6E90\u515C\u5E95 + 24h \u65F6\u7A97\uFF08\u504F\u5B8C\u6574\u4EA7\u7EBF\uFF09</li><li>\u9762\u5411\u80B2\u513F\u573A\u666F\u7684\u65E5\u62A5\u6A21\u677F\u5316\u8F93\u51FA\uFF08\u504F\u5185\u5BB9\u6A21\u677F\u5DE5\u7A0B\uFF09</li><li>web_fetch \u88AB\u79C1\u7F51 IP \u7B56\u7565\u62E6\u622A\u540E\uFF0C\u5207\u6362\u6293\u53D6\u94FE\u8DEF\u5B8C\u6210\u5B9A\u65F6\u64AD\u62A5\uFF08\u504F\u6293\u53D6\u515C\u5E95\uFF09</li></ol>',48),r=[s];function h(t,n){return e(),i("div",null,r)}var u=l(o,[["render",h],["__file","course-map.html.vue"]]);export{u as default};
